def find_conflicts(sessions: Sequence[Session]) -> List[Tuple[Session, Session]]:
    """Return each conflicting pair once, ordered by input positions.
    Conflict: same day, overlapping times (strict), and sharing a room or group.
    """
    conflicts: List[Tuple[Session, Session]] = []
    for i, a in enumerate(sessions):
        for j in range(i + 1, len(sessions)):
            b = sessions[j]
            if a.day != b.day:
                continue
            if a.start_minutes < b.end_minutes and b.start_minutes < a.end_minutes:
                if _shares_resource(a, b):
                    conflicts.append((a, b))
    return conflicts
